const TYPE_COLORS = { paper: '--paper', post: '--post', project: '--project', org: '--org', dataset: '--dataset', finding: '--finding', principle: '--principle', workflow: '--workflow', package: '--package' };
const TYPE_LABEL = { paper: 'Paper', post: 'Post', project: 'Project', org: 'Organization', dataset: 'Dataset', finding: 'Finding', principle: 'Principle', workflow: 'Workflow', package: 'Daliesk package' };
const css = name => getComputedStyle(document.documentElement).getPropertyValue(name).trim();
const byId = new Map(KG.nodes.map(n => [n.id, n]));
const adjacency = new Map(KG.nodes.map(n => [n.id, []]));
for (const e of KG.edges) { if (byId.has(e.from) && byId.has(e.to)) { adjacency.get(e.from).push({ other: e.to, label: e.label, dir: 'out' }); adjacency.get(e.to).push({ other: e.from, label: e.label, dir: 'in' }); } }
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

// ---------- stats
const counts = {};
for (const n of KG.nodes) counts[n.type] = (counts[n.type] || 0) + 1;
document.getElementById('stats').innerHTML = Object.entries(TYPE_LABEL).filter(([t]) => counts[t]).map(([t, l]) => `<span><b>${counts[t]}</b>${l}${counts[t] === 1 ? '' : 's'}</span>`).join('') + `<span><b>${KG.edges.length}</b>edges</span>`;
document.getElementById('updated').textContent = KG.program.updated;

// ---------- program verdicts
const VERDICT_COLOR = { refuted: '--bad', supported: '--good', 'untuned number': '--warn' };
document.getElementById('verdicts').innerHTML = `<h2>${esc(KG.program.title)}</h2><p>${esc(KG.program.summary)}</p><div class="row">` + KG.program.verdicts.map(v => `<div class="v" style="--c: var(${VERDICT_COLOR[v.mark] || '--ink-3'})"><span class="mark">${esc(v.mark)}</span><b>${esc(v.claim)}</b><span class="d">${esc(v.detail)}</span></div>`).join('') + `</div>`;

// ---------- filters
const state = { types: new Set(Object.keys(TYPE_LABEL)), workflows: new Set(), themes: new Set(), sources: new Set(), query: '', selected: null };
const allWorkflows = ['W1', 'W2', 'W3', 'W4'];
const allThemes = [...new Set(KG.nodes.flatMap(n => n.themes || []))].sort();
const allSources = [...new Set(KG.nodes.map(n => n.source).filter(Boolean))].sort();
function chips(container, items, set, colorOf) {
  const el = document.getElementById(container);
  el.innerHTML = items.map(i => `<button class="chip" data-v="${esc(i.v)}" aria-pressed="${set.has(i.v)}" ${colorOf ? `style="--c: var(${colorOf(i.v)})"` : ''}>${colorOf ? '<span class="dot"></span>' : ''}${esc(i.l)}</button>`).join('');
  el.querySelectorAll('.chip').forEach(b => b.addEventListener('click', () => { const v = b.dataset.v; if (set.has(v)) set.delete(v); else set.add(v); b.setAttribute('aria-pressed', set.has(v)); render(); }));
}
chips('type-chips', Object.entries(TYPE_LABEL).map(([v, l]) => ({ v, l })), state.types, t => TYPE_COLORS[t]);
chips('wf-chips', allWorkflows.map(v => ({ v, l: v })), state.workflows);
chips('theme-chips', allThemes.map(v => ({ v, l: v })), state.themes);
chips('source-chips', allSources.map(v => ({ v, l: v })), state.sources);
document.getElementById('search').addEventListener('input', e => { state.query = e.target.value.trim().toLowerCase(); render(); });
document.getElementById('legend').innerHTML = Object.entries(TYPE_LABEL).map(([t, l]) => `<div><i style="--c: var(${TYPE_COLORS[t]})"></i>${l}</div>`).join('');

function visible(n) {
  if (!state.types.has(n.type)) return false;
  if (state.workflows.size && !(n.workflows || []).some(w => state.workflows.has(w))) return false;
  if (state.themes.size && !(n.themes || []).some(t => state.themes.has(t))) return false;
  if (state.sources.size && !state.sources.has(n.source)) return false;
  if (state.query) { const hay = `${n.id} ${n.title} ${n.subtitle || ''} ${n.summary || ''} ${(n.themes || []).join(' ')}`.toLowerCase(); if (!hay.includes(state.query)) return false; }
  return true;
}

// ---------- layout (precomputed force simulation, then static)
const LEAF = new Set(['paper', 'finding', 'post']);
const nodes = KG.nodes.map((n, i) => ({ ...n, x: Math.cos(i * 2.399) * (120 + i * 2.2), y: Math.sin(i * 2.399) * (120 + i * 2.2), vx: 0, vy: 0, r: LEAF.has(n.type) ? 5 : 8 }));
const idx = new Map(nodes.map((n, i) => [n.id, i]));
const links = KG.edges.filter(e => idx.has(e.from) && idx.has(e.to)).map(e => ({ s: idx.get(e.from), t: idx.get(e.to), label: e.label }));
function simulate(iterations) {
  const n = nodes.length;
  for (let it = 0; it < iterations; it++) {
    const alpha = 1 - it / iterations;
    for (let i = 0; i < n; i++) {
      const a = nodes[i];
      for (let j = i + 1; j < n; j++) {
        const b = nodes[j]; let dx = a.x - b.x, dy = a.y - b.y; let d2 = dx * dx + dy * dy; if (d2 < 1) { dx = (Math.random() - 0.5); dy = (Math.random() - 0.5); d2 = 1; }
        const hubs = (LEAF.has(a.type) ? 0 : 1) + (LEAF.has(b.type) ? 0 : 1);
        const f = (1600 + hubs * 2600) / d2; const d = Math.sqrt(d2); const fx = dx / d * f, fy = dy / d * f;
        a.vx += fx; a.vy += fy; b.vx -= fx; b.vy -= fy;
      }
    }
    for (const l of links) {
      const a = nodes[l.s], b = nodes[l.t]; const dx = b.x - a.x, dy = b.y - a.y; const d = Math.sqrt(dx * dx + dy * dy) || 1;
      const rest = LEAF.has(a.type) && LEAF.has(b.type) ? 60 : 130; const f = (d - rest) * 0.018;
      a.vx += dx / d * f; a.vy += dy / d * f; b.vx -= dx / d * f; b.vy -= dy / d * f;
    }
    for (const a of nodes) { const g = LEAF.has(a.type) ? 0.0035 : 0.002; a.vx -= a.x * g; a.vy -= a.y * g; a.x += a.vx * alpha * 0.6; a.y += a.vy * alpha * 0.6; a.vx *= 0.5; a.vy *= 0.5; }
  }
}
simulate(520);

// ---------- canvas
const canvas = document.getElementById('graph');
const ctx = canvas.getContext('2d');
const view = { k: 1, tx: 0, ty: 0 };
function fit() {
  const wrap = document.getElementById('graph-wrap');
  const w = wrap.clientWidth, h = Math.max(420, Math.min(760, window.innerHeight * 0.7));
  canvas.width = w * devicePixelRatio; canvas.height = h * devicePixelRatio; canvas.style.height = h + 'px';
  const xs = nodes.map(n => n.x), ys = nodes.map(n => n.y);
  const minX = Math.min(...xs), maxX = Math.max(...xs), minY = Math.min(...ys), maxY = Math.max(...ys);
  view.k = Math.min(w / (maxX - minX + 80), h / (maxY - minY + 80));
  view.tx = w / 2 - ((minX + maxX) / 2) * view.k; view.ty = h / 2 - ((minY + maxY) / 2) * view.k;
  render();
}
function render() {
  const w = canvas.width / devicePixelRatio, h = canvas.height / devicePixelRatio;
  ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
  ctx.clearRect(0, 0, w, h);
  const vis = nodes.map(visible);
  const sel = state.selected; const neigh = new Set(sel ? adjacency.get(sel).map(e => e.other) : []);
  ctx.lineWidth = 1;
  for (const l of links) {
    if (!vis[l.s] || !vis[l.t]) continue;
    const a = nodes[l.s], b = nodes[l.t];
    const hot = sel && (a.id === sel || b.id === sel);
    ctx.strokeStyle = hot ? css('--accent') : css('--hair-2'); ctx.globalAlpha = hot ? 1 : 0.45;
    ctx.beginPath(); ctx.moveTo(a.x * view.k + view.tx, a.y * view.k + view.ty); ctx.lineTo(b.x * view.k + view.tx, b.y * view.k + view.ty); ctx.stroke();
  }
  ctx.globalAlpha = 1;
  ctx.font = '11px "IBM Plex Sans", system-ui, sans-serif';
  for (let i = 0; i < nodes.length; i++) {
    const n = nodes[i]; if (!vis[i]) continue;
    const x = n.x * view.k + view.tx, y = n.y * view.k + view.ty;
    const focus = !sel || n.id === sel || neigh.has(n.id);
    ctx.globalAlpha = focus ? 1 : 0.25;
    ctx.fillStyle = css(TYPE_COLORS[n.type] || '--ink-3');
    ctx.beginPath(); ctx.arc(x, y, n.r * (n.id === sel ? 1.6 : 1), 0, Math.PI * 2); ctx.fill();
    if (n.id === sel) { ctx.strokeStyle = css('--ink'); ctx.lineWidth = 2; ctx.stroke(); ctx.lineWidth = 1; }
    if (!LEAF.has(n.type) || n.id === sel || neigh.has(n.id) || view.k > 1.6) {
      const label = n.title.length > 42 ? n.title.slice(0, 40) + '…' : n.title;
      const tw = ctx.measureText(label).width;
      ctx.fillStyle = css('--bg'); ctx.globalAlpha = focus ? 0.85 : 0.2; ctx.fillRect(x + n.r + 2, y - 6, tw + 4, 13); ctx.globalAlpha = focus ? 1 : 0.25;
      ctx.fillStyle = css('--ink'); ctx.fillText(label, x + n.r + 4, y + 4);
    }
  }
  ctx.globalAlpha = 1;
}
let drag = null;
canvas.addEventListener('pointerdown', e => { drag = { x: e.clientX, y: e.clientY, tx: view.tx, ty: view.ty, moved: false }; canvas.setPointerCapture(e.pointerId); });
canvas.addEventListener('pointermove', e => { if (!drag) return; const dx = e.clientX - drag.x, dy = e.clientY - drag.y; if (Math.abs(dx) + Math.abs(dy) > 3) drag.moved = true; view.tx = drag.tx + dx; view.ty = drag.ty + dy; render(); });
canvas.addEventListener('pointerup', e => {
  if (drag && !drag.moved) {
    const rect = canvas.getBoundingClientRect(); const px = e.clientX - rect.left, py = e.clientY - rect.top;
    let best = null, bestD = 14;
    nodes.forEach((n, i) => { if (!visible(n)) return; const d = Math.hypot(n.x * view.k + view.tx - px, n.y * view.k + view.ty - py); if (d < bestD) { bestD = d; best = n; } });
    select(best ? best.id : null);
  }
  drag = null;
});
canvas.addEventListener('wheel', e => { e.preventDefault(); const rect = canvas.getBoundingClientRect(); const px = e.clientX - rect.left, py = e.clientY - rect.top; const f = e.deltaY < 0 ? 1.12 : 1 / 1.12; view.tx = px - (px - view.tx) * f; view.ty = py - (py - view.ty) * f; view.k *= f; render(); }, { passive: false });
window.addEventListener('resize', fit);

// ---------- detail
function select(id) {
  state.selected = id; render();
  const el = document.getElementById('detail');
  if (!id) { el.innerHTML = '<p class="eyebrow">Selected node</p><p class="empty">Nothing selected.</p>'; return; }
  const n = byId.get(id);
  const rel = adjacency.get(id);
  el.innerHTML = `<p class="eyebrow">${esc(TYPE_LABEL[n.type] || n.type)}${n.source ? ' · ' + esc(n.source) : ''}</p>
    <h2>${esc(n.title)}</h2>
    <div class="meta">${[n.subtitle, n.year, n.id.startsWith('2') ? 'arXiv ' + esc(n.id) : ''].filter(Boolean).map(esc).join(' · ')}</div>
    ${n.summary ? `<p>${esc(n.summary)}</p>` : ''}
    ${n.result ? `<p><b>What it measured or built.</b> ${esc(n.result)}</p>` : ''}
    ${n.relevance ? `<p><b>Why it matters to Daliesk.</b> ${esc(n.relevance)}</p>` : ''}
    <div>${(n.workflows || []).map(w => `<span class="tag">${esc(w)}</span>`).join('')}${(n.principles || []).map(p => `<span class="tag">${esc(p)}</span>`).join('')}${(n.themes || []).map(t => `<span class="tag">${esc(t)}</span>`).join('')}</div>
    ${n.url ? `<p><a href="${esc(n.url)}" target="_blank" rel="noopener">Open source ↗</a></p>` : ''}
    <p class="eyebrow" style="margin-top:14px">Connections (${rel.length})</p>
    ${rel.length ? `<ul class="edges">${rel.map(e => { const o = byId.get(e.other); return `<li><span class="mono">${esc(e.dir === 'out' ? e.label : '← ' + e.label)}</span> · <button data-id="${esc(e.other)}">${esc(o.title)}</button></li>`; }).join('')}</ul>` : '<p class="empty">No recorded edges yet.</p>'}`;
  el.querySelectorAll('button[data-id]').forEach(b => b.addEventListener('click', () => select(b.dataset.id)));
}

// ---------- lists
function list(title, items, fmt) { return `<div class="card"><h3>${esc(title)}</h3>${items.length ? `<ol>${items.map(fmt).join('')}</ol>` : '<p class="empty">Pending.</p>'}</div>`; }
const papers = KG.nodes.filter(n => n.type === 'paper');
const reading = (KG.readingOrder || []).map(id => byId.get(id)).filter(Boolean);
const findings = KG.nodes.filter(n => n.type === 'finding');
document.getElementById('lists').innerHTML =
  list('Read first', reading, n => `<li><b><button class="linkish" data-id="${esc(n.id)}">${esc(n.title)}</button></b> — ${esc(n.relevance || n.summary || '')}</li>`) +
  list('AI Village findings recorded', findings, n => `<li><b><button class="linkish" data-id="${esc(n.id)}">${esc(n.title)}</button></b> — ${esc(n.summary || '')}</li>`) +
  list(`All papers (${papers.length})`, papers.sort((a, b) => (b.year || '').localeCompare(a.year || '')), n => `<li><button class="linkish" data-id="${esc(n.id)}">${esc(n.title)}</button> <span class="mono">${esc(n.year || '')}</span></li>`);
document.querySelectorAll('button.linkish').forEach(b => { b.style.cssText = 'background:none;border:0;padding:0;color:var(--accent);cursor:pointer;font:inherit;text-align:left;text-decoration:underline'; b.addEventListener('click', () => { select(b.dataset.id); document.getElementById('graph-wrap').scrollIntoView({ behavior: 'smooth', block: 'center' }); }); });

fit();
if (window.matchMedia) { window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', render); }
</script>

