52	  .rail nav a { display: flex; align-items: baseline; gap: 10px; padding: 7px 10px; border-radius: 6px; text-decoration: none; color: var(--ink-2); font-size: 14px; }
53	  .rail nav a:hover { background: var(--surface-2); color: var(--ink); }
54	  .rail nav a.active { background: var(--ink); color: var(--ground); }
