57	  main { padding: 28px 36px 80px; display: flex; flex-direction: column; gap: 44px; min-width: 0; }
58	  header.masthead { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 24px; align-items: end; padding-bottom: 22px; border-bottom: 1px solid var(--hair); }
59	  header.masthead p { margin-top: 12px; color: var(--ink-2); font-size: 16px; }
60	  .legend { display: flex; flex-wrap: wrap; gap: 8px 14px; align-items: center; }
61	  .legend .item { display: inline-flex; align-items: center; gap: 7px; font-size: 13px; color: var(--ink-2); }
62	  .swatch { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }
63	  .swatch.human { background: var(--human); } .swatch.s { background: var(--s); } .swatch.d { background: var(--d); } .swatch.store { background: var(--store); } .swatch.gate { background: var(--gate); }
64	  section { display: flex; flex-direction: column; gap: 16px; scroll-margin-top: 12px; }
65	  .section-head { display: flex; flex-direction: column; gap: 6px; }
66	  .section-head p { color: var(--ink-2); }
67	  .goal { font-family: "Bricolage Grotesque", sans-serif; font-weight: 500; font-size: 18px; color: var(--ink-2); }
68	  .toolbar { display: flex; flex-wrap: wrap; gap: 10px 18px; align-items: center; justify-content: space-between; }
69	  .chips { display: flex; flex-wrap: wrap; gap: 6px; }
70	  .chip { border: 1px solid var(--hair); background: var(--surface); color: var(--ink-2); border-radius: 999px; padding: 4px 11px; font-size: 13px; cursor: pointer; font-family: inherit; }
71	  .chip[aria-pressed="true"] { background: var(--ink); color: var(--ground); border-color: var(--ink); }
72	  .chip:focus-visible, button:focus-visible, .node:focus-visible, input:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
73	  .stepper { display: inline-flex; align-items: center; gap: 8px; }
74	  .stepper button { border: 1px solid var(--hair); background: var(--surface); color: var(--ink); border-radius: 6px; padding: 4px 10px; font: inherit; cursor: pointer; }
75	  .stepper .pos { font-family: "Martian Mono", monospace; font-size: 12px; color: var(--ink-2); min-width: 8ch; text-align: center; font-variant-numeric: tabular-nums; }
76	  .stage-wrap { display: grid; grid-template-columns: 1fr; gap: 14px; align-items: start; }
77	  .diagram { background: var(--surface); border: 1px solid var(--hair-2); border-radius: 10px; overflow-x: auto; overflow-y: hidden; box-shadow: var(--shadow); }
78	  .diagram svg { display: block; }
79	  .inspector { background: var(--surface); border: 1px solid var(--hair-2); border-radius: 10px; padding: 18px 18px 20px; box-shadow: var(--shadow); display: flex; flex-direction: column; gap: 12px; }
80	  .diagram-caption { font-size: 12.5px; color: var(--ink-3); display: flex; justify-content: space-between; gap: 12px; }
