85	  .badge.t-D { color: var(--d); border-color: var(--d); background: var(--d-soft); }
86	  .badge.t-S { color: var(--s); border-color: var(--s); background: var(--s-soft); }
87	  .badge.t-DS { color: var(--ink); border-color: var(--hair); background: linear-gradient(90deg, var(--d-soft), var(--s-soft)); }
