102	  .node.selected rect.box { stroke: var(--ink); stroke-width: 2; }
103	  .node text.title { font-family: "Atkinson Hyperlegible", system-ui, sans-serif; font-size: 12.5px; fill: var(--ink); font-weight: 700; }
