559	  const lines = [];
560	  let line = '';
561	  for (const w of words) {
562	    if ((line + ' ' + w).trim().length > 19 && line) { lines.push(line); line = w; } else line = (line + ' ' + w).trim();
563	  }
564	  if (line) lines.push(line);
565	  return lines.slice(0, 2);
