// Second pass: the frozen drop pair's recorded reading, read from the record,
// the fold, and the results note as they stand on 2026-09-18.
import { readFileSync, writeFileSync } from 'node:fs'

const GH = 'https://github.com/lbjlincoln/deepseek-harness/blob/claude/coding-agent-harness-u9l4gt/'
const lines = readFileSync('kg.html', 'utf8').split('\n')
const i = lines.findIndex(l => l.startsWith('const KG = '))
const kg = JSON.parse(lines[i].replace(/^const KG = /, '').replace(/;\s*$/, ''))
const node = id => {
  const n = kg.nodes.find(x => x.id === id)
  if (!n) throw new Error('missing ' + id)
  return n
}

// The rerun: a record and a fold exist; the pair was cut at 25 of 32 cells.
Object.assign(node('running:frozen-drop-pair'), {
  title: 'The frozen drop pair (ran 2026-09-18, cut at 25 of 32 cells, inconclusive)',
  subtitle: 'the rerun that did not replicate the one harness-mechanism reading',
  summary: 'The drop comparison ran again on 2026-09-18 as one frozen experiment from the checked-in plan e5-drop-frozen-t5, on the fixed overlay, over eight sealed tier-5 tasks at two repetitions. A container restart killed the driver at 23:00 UTC after 25 of its 32 cells, before the fold, so the record is partial and the verdict comes from an offline fold over the pairs that completed: seven paired repetitions, 7 of 7 certified with the cheap model’s transcript kept against 5 of 7 with a fresh child per rung, delta −0.2857, interval [−0.5714, 0], inconclusive. On build-schedule and conf-canon, two of the offline fold’s three flip tasks, the kept transcript certified both repetitions and the fresh child one each. The nine candidate cells that never ran are queued with the per-rung share on the spawn arm; nothing is promoted on the drop.',
  url: GH + 'data/proving-ground/folds/2026-09-18-e5-drop-frozen-spawn-against-route-t5.json',
})

const drop = node('finding:drop-the-cheap-transcript')
drop.title = 'Not replicated: a fresh child per rung beats keeping the transcript'
drop.subtitle = 'offline fold 14 of 16 against 11; the frozen pair reads the other way on its seven complete pairs'
drop.year = '2026-09-18'
drop.summary = 'The same cheap-then-strong ladder with a fresh in-process child per rung, so the strong model inherits the workspace and the directive but not the cheap model’s transcript, certified 14 of 16 against 11 with the transcript kept as an offline fold of two arms that ran an hour apart and were never frozen together: three flips all one way, all on the hardest tasks, 0.1875, [0.0625, 0.3125]. The frozen pair on the fixed overlay, run on 2026-09-18 and cut by a container restart at 25 of 32 cells, reads the other way on its seven complete pairs — 5 of 7 for the fresh child against 7 of 7 for the kept transcript, −0.2857, [−0.5714, 0], inconclusive — and on two of the fold’s three flip tasks the kept transcript certified both repetitions. In both readings every fresh-child miss is a cell whose cheap rung alone spent the token cap before the strong rung ran, the allocation defect the per-rung share closes. Nothing is promoted on the drop, and the pair’s remaining cells are queued with the share on the spawn arm.'

kg.program.verdicts[6] = {
  mark: 'not replicated',
  claim: 'A fresh child per rung beats keeping the cheap model’s transcript',
  detail: 'The offline fold read 14 of 16 against 11, 0.1875, [0.0625, 0.3125], three flips all one way, from arms that ran an hour apart and were never frozen together. The frozen pair on the fixed overlay, cut by a container restart at 25 of 32 cells, reads 5 of 7 against 7 of 7 on its complete pairs, −0.2857, [−0.5714, 0], inconclusive, with two of the fold’s three flip tasks flipping the other way. Nothing is promoted on the drop.',
}
kg.program.verdicts[8] = {
  mark: 'partial record',
  claim: 'The frozen drop pair, rerun 2026-09-18',
  detail: 'The rerun that would have turned the one harness-mechanism reading into a promotion: the same ladder on the fixed overlay, from the checked-in plan. A container restart killed its driver at 23:00 UTC after 25 of 32 cells, and the verdict above comes from an offline fold over the seven pairs that completed. The nine candidate cells that never ran are queued with the per-rung share on the spawn arm.',
}
kg.program.updated = 'Last updated 2026-09-18 · thirty records and eleven folds through 2026-09-08 plus the frozen drop pair’s partial record and its fold today, all under data/proving-ground and on the published dashboard · five refutations, one frozen promotion, one reading that did not replicate, E6 running'

const hp = node('project:hypothesis-program')
hp.summary = hp.summary.replace(
  'The two slices the results demanded have landed, and the drop pair and E6 are the first experiments to run on them.',
  'The two slices the results demanded have landed; the frozen drop pair was the first experiment to run on them, and it did not replicate the offline fold before a container restart cut it at 25 of 32 cells.',
)

const runs = node('dataset:proving-ground-runs')
runs.subtitle = 'thirty-one records and twelve folds, one dashboard, one corpus fold'
runs.summary = runs.summary.replace(
  'It holds thirty records and eleven folds, the whole hypothesis program among them,',
  'It holds thirty-one records and twelve folds, the whole hypothesis program among them, the newest being the frozen drop pair a container restart cut at 25 of 32 cells and the fold over the pairs it completed,',
)

const out = 'const KG = ' + JSON.stringify(kg) + ';'
if (out.includes('script')) throw new Error('script token in data')
lines[i] = out
writeFileSync('kg.html', lines.join('\n'))
console.log('ok', kg.nodes.length, kg.edges.length)

